'use client'

import Link from 'next/link'
import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import { getUserRole } from '@/lib/supabase/roles'
import type { AnalyticsDateRange, VendorAnalyticsDashboard } from '@/lib/vendor/analytics'
import { vendorAnalyticsService } from '@/lib/vendor/analytics'
import { AnalyticsChart } from '../components/AnalyticsChart'
import { AnalyticsKpiCard } from '../components/AnalyticsKpiCard'
import { AnalyticsPerformanceTable } from '../components/AnalyticsPerformanceTable'
import { CatalogFeedback } from '../components/CatalogFeedback'

export default function VendorAnalyticsPage() { const [vendorId, setVendorId] = useState<string | null>(null); const [range, setRange] = useState<AnalyticsDateRange>('30d'); const [dashboard, setDashboard] = useState<VendorAnalyticsDashboard | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); useEffect(() => { void createClient().auth.getUser().then(({ data: { user } }) => { if (user && (getUserRole(user) === 'vendor' || getUserRole(user) === 'admin')) setVendorId(user.id); else setLoading(false) }) }, []); useEffect(() => { if (!vendorId) return; const currentVendorId = vendorId; async function load() { setLoading(true); try { setDashboard(await vendorAnalyticsService.getDashboard(currentVendorId, range)); setError('') } catch { setError('We could not load analytics for this vendor.') } finally { setLoading(false) } } void load() }, [vendorId, range]); if (loading) return <main className="vendor-page"><div className="operations-shell"><CatalogFeedback type="loading">Loading vendor analytics...</CatalogFeedback></div></main>; if (!dashboard) return <main className="vendor-page"><div className="operations-shell"><CatalogFeedback type="error">{error || 'Analytics are unavailable.'}</CatalogFeedback></div></main>; const kpi = dashboard.kpis; return <main className="vendor-page"><header className="vendor-header"><Link href="/vendor" className="logo logo-active">Furnish<span>AI</span></Link><nav><Link href="/vendor/products" className="btn-skip">Catalog</Link><Link href="/vendor/notifications" className="btn-skip">Notifications</Link><span className="vendor-header-label">Analytics</span></nav></header><div className="analytics-shell"><div className="analytics-heading"><div><p className="vendor-eyebrow">Vendor portal / Phase 08</p><h1>Performance, without guesswork.</h1><p>Operational catalog health is available now. Customer behavior metrics will appear when vendor-scoped analytics aggregation is connected.</p></div><div className="analytics-controls"><label><span>Date range</span><select value={range} onChange={(event) => setRange(event.target.value as AnalyticsDateRange)}><option value="7d">Last 7 days</option><option value="30d">Last 30 days</option><option value="90d">Last 90 days</option></select></label><button type="button" className="btn-skip" onClick={() => void vendorAnalyticsService.exportPerformance(vendorId ?? '', range)}>Export CSV</button></div></div>{error ? <CatalogFeedback type="error">{error}</CatalogFeedback> : null}<section className="analytics-kpi-grid"><AnalyticsKpiCard label="Total products" value={kpi.totalProducts} /><AnalyticsKpiCard label="Active products" value={kpi.activeProducts} /><AnalyticsKpiCard label="Approved products" value={kpi.approvedProducts} /><AnalyticsKpiCard label="Pending approval" value={kpi.pendingProducts} /><AnalyticsKpiCard label="Rejected products" value={kpi.rejectedProducts} /><AnalyticsKpiCard label="Product views" value={kpi.productViews} available={dashboard.availableMetrics.includes('productViews')} /><AnalyticsKpiCard label="Product clicks" value={kpi.productClicks} available={dashboard.availableMetrics.includes('productClicks')} /><AnalyticsKpiCard label="Enquiries" value={kpi.enquiries} available={dashboard.availableMetrics.includes('enquiries')} /></section><section className="analytics-panel analytics-trend-panel"><div className="analytics-panel-heading"><div><h2>Engagement trend</h2><span>{new Date(dashboard.range.from).toLocaleDateString('en-IN')} – {new Date(dashboard.range.to).toLocaleDateString('en-IN')}</span></div></div><AnalyticsChart points={dashboard.trend} /></section><div className="analytics-performance-grid"><AnalyticsPerformanceTable title="Top-performing products" products={dashboard.topProducts} /><AnalyticsPerformanceTable title="Products needing attention" products={dashboard.poorProducts} /></div><p className="analytics-footnote">Analytics are scoped to the authenticated vendor. Metrics marked unavailable require backend event aggregation and are not estimated in this dashboard.</p></div></main> }